class CursorExpired(Exception):
    pass

def make_fake():
    state = {"uses": 0, "expired_once": False}
    def fake(cursor, size=10):
        state["uses"] += 1
        if state["uses"] > 3 and not state["expired_once"]:
            state["expired_once"] = True  # the long-lived first cursor dies once
            state["uses"] = 0              # a fresh walk gets a fresh session
            raise CursorExpired("cursor lifetime exceeded")
        start = 0 if cursor is None else cursor
        chunk = DATA[start:start + size]
        nxt = start + size if start + size < len(DATA) else None
        return chunk, nxt
    return fake

def export():
    fake = make_fake()
    seen, cursor = set(), None
    while True:
        try:
            chunk, cursor = fake(cursor)
        except CursorExpired:
            cursor = None  # restart the walk...
            continue        # ...but keep 'seen'
        fresh = [i for i in chunk if i not in seen]
        seen.update(chunk)
        if cursor is None:
            return len(seen), "completed"

