def run(breaker, user_requests=50, retries=3, threshold=5):
    calls, failures = 0, 0
    state = "closed"
    for _ in range(user_requests):
        if breaker and state == "open":
            continue  # fail fast locally: zero calls to the dead API
        for _ in range(1 + retries):
            calls += 1
            failures += 1  # API is down: every call fails
        if breaker and failures >= threshold:
            state = "open"
    return calls

