class Limiter:
    def __init__(self, window=20):
        self.window = window
        self.blocked_until = window  # budget already spent: we start AT the limit
    def call(self, t):
        if t < self.blocked_until:
            return 429, self.blocked_until - t
        self.blocked_until = t + self.window  # budget spent; window starts
        return 200, None

def run(waits):
    lim, t, out = Limiter(), 0, []
    status, retry_after = lim.call(t)
    out.append((t, status))
    for w in waits:
        t += retry_after if w == "header" else w
        status, retry_after = lim.call(t)
        out.append((t, status))
        if status == 200:
            break
    return out

