def run(policy, total=40, budget=30):
    remaining, made, rejected = budget, 0, 0
    for i in range(total):
        if policy == "proactive" and remaining <= 5:
            # slow down and let the window refill instead of spending the last tokens
            remaining = budget
        if remaining == 0:
            rejected += 1
            remaining = budget  # window eventually resets, after a 429 taught us
