def naive(chunks):
    ok, bad = 0, 0
    for ch in chunks:
        for line in ch.decode().splitlines():
            try:
                json.loads(line); ok += 1
            except json.JSONDecodeError:
                bad += 1
    return ok, bad

def buffered(chunks):
    buf, ok = "", 0
    for ch in chunks:
        buf += ch.decode()
        while "\n" in buf:
            line, buf = buf.split("\n", 1)
            if line.strip():
                json.loads(line); ok += 1
    if buf.strip():
        json.loads(buf); ok += 1
    return ok

