MAX_ATTEMPTS = 3
attempts = {}
dead_letter = []
processed = []

EVENTS = ["evt-poison", "evt-good-1", "evt-good-2"]

def handle(event_id):
    if event_id == "evt-poison":
        raise ValueError("payload references a deleted object: can NEVER succeed")
    processed.append(event_id)

for event_id in EVENTS:
    while True:
        try:
            handle(event_id)
            break
        except ValueError:
            attempts[event_id] = attempts.get(event_id, 0) + 1
            if attempts[event_id] >= MAX_ATTEMPTS:
                dead_letter.append(event_id)  # parked, alerted, NOT dropped
                break
            # else: provider will retry later; move on for this model

print("processed:", processed)
print("dead-lettered after", MAX_ATTEMPTS, "attempts:", dead_letter)

import json
from urllib.parse import parse_qs

RAW = "event=order.paid&order=55"
CT_JSON = "application/json"
CT_FORM = "application/x-www-form-urlencoded"

def receive_strict(raw):
    return json.loads(raw)

