    receive_strict(RAW)
except json.JSONDecodeError as e:
    print("json-only receiver:", type(e).__name__, "-> HTTP 500")

def receive(content_type, raw):
    if content_type == CT_FORM:
        fields = {k: v[0] for k, v in parse_qs(raw).items()}
        return {"type": fields["event"], "order": int(fields["order"])}
    return json.loads(raw)

print("branched receiver:", receive(CT_FORM, RAW))

